```jac
"""combine intervals.

Overlapping intervals are reduced to their intersection.
"""
def getIntersections(intervals: list[tuple[float, float]]) -> list[tuple[float, float]] {
    if not intervals {
        return [];
    }
    intervals.sort();
    max_to = intervals[0][1];
    all_sections: list[list[float]] = [];
    sections: list[float] = [intervals[0][0], intervals[0][1]];
    for (this_from, this_to) in intervals[1:] {
        if this_from > max_to {
            all_sections.append(sections);
            max_to = this_to;
            sections = [];
        }
        max_to = max(max_to, this_to);
        sections.append(this_from);
        sections.append(this_to);
    }
    all_sections.append(sections);
    new_intervals: list[tuple[float, float]] = [];
    for section_group in all_sections {
        section_group.sort();
        last_x = section_group[0];
        for x in section_group[1:] {
            if last_x == x {
                continue;
            }
            new_intervals.append((last_x, x));
            last_x = x;
        }
    }
    return new_intervals;
}
