"""If subsequence exists in sequence, return True. otherwise return False.
    can be modified to return the appropriate index (useful to test WHERE a
    chain is converged)
    """
def find_subsequence(subseq: list[int | str], seq: list[int | str]) -> bool {
    (i, n, m) = (-1, len(seq), len(subseq));
    try {
        while True {
            i = seq.index(subseq[0], i + 1, n - m + 1);
            if subseq == seq[i:(i + m)] {
                return True;
            }
        }
    } except ValueError {
        return False;
    }
}
