"""Permutes the provided list."""
def permutations(values: list[str]) -> str | list[str] {
    if len(values) == 1 {
        return values[0];
    }
    ret = [];
    i = 0;
    for item in values {
        values.remove(item);
        perms = permutations(values);
        for perm in perms {
            ret.append(item + perm);
        }
        values.insert(i, item);
        i += 1;
    }
    return ret;
}
