"""Process metadata arguments into a field-to-value dict."""
def clean_meta_args(args: Iterable[str]) -> dict[str, str] {
    results = {};
    for arg in args {
        parts = [x.strip() for x in arg.split("=", 1)];
        if len(parts) == 2 {
            if not parts[0] {
                raise ValueError("Empty field name");
            }
            (field, value) = parts;
        } else {
            raise ValueError("meta argument isn't in 'field=value' format");
        }
        if not value {
            continue;
        }
        results[field] = value;
    }
    return results;
}
