"""Utility function to evenly split a list. Handles edge cases."""
def splitit(l: list[int], n: int) -> list[list[int]] {
    if len(l) < n {
        n = len(l);
    }
    s = len(l) // n;
    m = len(l) % (s * n);
    r = [];
    p = 0;
    for i in range(n) {
        if i < m {
            r.append(l[p:(p + s + 1)]);
            p += s + 1;
        } else {
            r.append(l[p:(p + s)]);
            p += s;
        }
    }
    return r;
