"""Unpacks a string that was packed by packLine."""
def unpackLine(string: str, separator: str = "|") -> list[str] {
    result: list[str] = [];
    token: str | None = None;
    escaped = False;
    for char in string {
        if token is None {
            token = "";
        }
        if escaped and char in ('\\', separator) {
            token += char;
            escaped = False;
            continue;
        }
        escaped = char == '\\';
        if escaped {
            continue;
        }
        if char == separator {
            result.append(token);
            token = "";
        } else {
            token += char;
        }
    }
    if token is not None {
        result.append(token);
    }
    return result;
}
