def decode(bp_sp: str) -> tuple[int, int] {
    row_bits = '';
    col_bits = '';
    for x in range(0, 7) {
        if bp_sp[x] == 'F' {
            row_bits = f"{row_bits}0";
        } elif bp_sp[x] == 'B' {
            row_bits = f"{row_bits}1";
        }
    }
    for x in range(7, 10) {
        if bp_sp[x] == 'L' {
            col_bits = f"{col_bits}0";
        } elif bp_sp[x] == 'R' {
            col_bits = f"{col_bits}1";
        }
    }
    return (int(row_bits, 2), int(col_bits, 2));
}
