def pascal(row: int, column: int) -> int {
    if column > row {
        return 0;
    }
    if row == 0 {
        return 1;
    }
    if column == 0 {
        return 1;
    }
    return pascal(row - 1, column) + pascal(row - 1, column - 1);
}
