"""List of N-1 ratios from N proportions."""
def _unpack_proportions(values: list[float]) -> list[float] {
    if len(values) == 1 {
        return [];
    }
    half = len(values) // 2;
    (num, denom) = (sum(values[half:]), sum(values[:half]));
    assert num > 0 and denom > 0;
    ratio = num / denom;
    return [ratio] + _unpack_proportions(values[:half]) + _unpack_proportions(values[half:]);
}
```

```jac
"""Load graph and costs of edges from serialized data string."""
def load(data: str) -> tuple[dict[int, set[int]], dict[tuple[int, int], int]] {
    lines = data.splitlines();
    graph: dict[int, set[int]] = {};
    costs: dict[tuple[int, int], int] = {};
    for line in lines {
        (source, dest, cost) = map(int, line.split());
        if source not in graph {
            graph[source] = set();
        }
        if dest not in graph {
            graph[dest] = set();
        }
        graph[source].add(dest);
        graph[dest].add(source);
        costs[(source, dest)] = cost;
        costs[(dest, source)] = cost;
    }
    return (graph, costs);
}
