def remove_from_qset_definition(qset_definition: dict[str, int | list[str] | list], `node: str) -> dict[str, int | list[str] | list] {
    threshold = qset_definition['threshold'] as int;
    validators = qset_definition['validators'] as list[str];
    if `node in validators {
        validators = validators.copy();
        validators.remove(`node);
        threshold -= 1;
    }
    inner_quorum_sets = [
        remove_from_qset_definition(inner_qset_definition, `node)
        for inner_qset_definition in (qset_definition['innerQuorumSets'] as list[dict[str, int | list[str] | list]])
    ];
    return {
        'threshold': threshold,
        'validators': validators,
        'innerQuorumSets': inner_quorum_sets
    };
}
