def minRemoveToMakeValid(s: str) -> str {
    (opens, closes) = ([], []);
    for (i, c) in enumerate(s) {
        if c == '(' {
            opens.append(i);
        } elif c == ')' {
            if len(opens) == 0 {
                closes.append(i);
            } else {
