Thereafter values are intersected with the existing allow set.
"""
def _update_allow(allow_set: set[str] | None, value: str | list[str] | set[str] | tuple[str, ...]) -> set[str] {
    adding_seq = hasattr(value, "__iter__") and not isinstance(value, str);
    if allow_set is None {
        allow_set = set();
        if adding_seq {
            allow_set.update(value);
        } else {
            allow_set.add(value);
        }
    } elif adding_seq {
        allow_set.intersection_update(value);
    } else {
        allow_set.intersection_update({value});
    }
    return allow_set;
}
