```jac
"""Tests to see if two line segments intersect."""
def test_line_seg_intersect(line1: list[float], line2: list[float]) -> bool {
    (p0_x, p0_y, p1_x, p1_y) = line1;
    (p2_x, p2_y, p3_x, p3_y) = line2;
    s1_x = p1_x - p0_x;
    s1_y = p1_y - p0_y;
    s2_x = p3_x - p2_x;
    s2_y = p3_y - p2_y;
    denom = -s2_x * s1_y + s1_x * s2_y;
    num_s = -s1_y * (p0_x - p2_x) + s1_x * (p0_y - p2_y);
    num_t = s2_x * (p0_y - p2_y) - s2_y * (p0_x - p2_x);
    if -1e-10 < denom < 1e-10 {
        abs_num_s = num_s if num_s >= 0.0 else -num_s;
        abs_num_t = num_t if num_t >= 0.0 else -num_t;
        return abs_num_s - abs_num_t < 1e-05;
    }
    s = num_s / denom;
    t = num_t / denom;
    return 0.0 <= s <= 1.0 and 0.0 <= t <= 1.0;
}
```

