"""Interpolates between two 2d points."""
def interpolate(
    x1: float, y1: float, x2: float, y2: float, current_step: int, total_steps: int
) -> tuple[float, float] {
    dx1 = (x2 - x1) / total_steps;
    dy1 = (y2 - y1) / total_steps;
    mx1 = x1 + dx1 * current_step;
    my1 = y1 + dy1 * current_step;
    return (mx1, my1);
}
