```jac
"""Receive file size and return a list of size ranges."""
def size_splitter(size: int, part_size: int) -> list[str] {
    result: list[str] = [];
    if size == 0 {
        result.append('0-0');
        return result;
    }
    span = part_size if part_size <= size else size;
    parts = max(size // span, 1);
    x = 0;
    size = size - 1;
    for i in range(parts) {
        y = x + span - 1;
        if size - y < span {
            y = size;
        }
        result.append(f'{x}-{y}');
        x = y + 1;
    }
    return result;
}
