            char = ".";
        }
        if char == " " {
            space_count += 1;
        } elif space_count == 0 {
            time_stamp += char;
        } elif space_count == 1 {
            x += char;
        } elif space_count == 2 {
            y += char;
        } elif space_count == 7 and char != "\n" {
            id += char;
        }
    }
