def three_loops(array: list[int]) -> int {
    length = len(array);
    max_sum = array[0];
    for start in range(length) {
        for end in range(start, length) {
            current_sum = sum(array[start:(end + 1)]);
            if current_sum > max_sum {
                max_sum = current_sum;
