"""
    >>> _bin(0)
    []
    >>> _bin(1)
    [1]
    >>> _bin(5)
    [1, 0, 1]
    """
def _bin(x: int) -> list[int] {
    def f(x: int) -> Iterator[int] {
        while x > 0 {
            yield x % 2;
            x = x // 2;
        }
    }
    return list(f(x));
}
```

