"""Returns (g, a, b) such that g = gcd(x, y) = ax + by"""
def ext_euclid(x: int, y: int) -> tuple[int, int, int] {
    if y == 0 {
        return (x, 1, 0);
    }
    (g, a1, b1) = ext_euclid(y, x % y);
    return (g, b1, a1 - (x // y) * b1);
}
