```jac
"""Returns the median value for a distribution."""
def dist_median(
    distribution: list[tuple[int | float, int]],
    count: int | float
) -> int | float | None {
    counter = 0;
    previous_value: int | float | None = None;
    for (value, instances) in distribution {
        counter += instances;
        if counter > count / 2.0 {
            if (
                not count % 2
                and counter - 1 == count / 2
                and previous_value is not None
            ) {
                return (value + previous_value) / 2.0;
            }
            return value;
        }
        previous_value = value;
    }
    return None;
}
```

```jac
""" checks to make sure that the card passes a luhn mod-10 checksum """
def cardLuhnChecksumIsValid(card_number: str) -> bool {
    sum = 0;
    num_digits = len(card_number);
    oddeven = num_digits & 1;
    for count in range(0, num_digits) {
        digit = int(card_number[count]);
        if not (count & 1 ^ oddeven) {
            digit = digit * 2;
        }
        if digit > 9 {
            digit = digit - 9;
        }
        sum = sum + digit;
    }
    return sum % 10 == 0;
}
```

