    """
def findPassingDistances(distances: list[list[float]], threshold: float) -> list[int] | int {
    min_ind = [];
    ind_ctr = 0;
    for val in distances {
        if val[0] < threshold {
            min_ind.append(ind_ctr);
        }
        ind_ctr += 1;
    }
    if len(min_ind) == 0 {
        return -1;
    }
    return min_ind;
}
