        return `obj;
    }
    if isinstance(`obj, str) {
        return 0;
    }
    if isinstance(`obj, list) {
        return sum(map(sum_non_red, `obj));
    }
    if isinstance(`obj, dict) {
        if 'red' in `obj.values() {
            return 0;
        }
