```jac
"""
Time: O(n)
Space: O(n lg n), for sorting
-
n = a_len + b_len + c_len
"""
def triplets(a: list[int], b: list[int], c: list[int]) -> int {
    a = list(sorted(set(a)));
    b = list(sorted(set(b)));
    c = list(sorted(set(c)));
    ai = bi = ci = 0;
    (a_len, c_len) = (len(a), len(c));
    answer = 0;
    while bi < len(b) {
        while ai < a_len and a[ai] <= b[bi] {
            ai += 1;
        }
        while ci < c_len and b[bi] >= c[ci] {
            ci += 1;
        }
        answer += ai * ci;
        bi += 1;
    }
    return answer;
}
