The second has the values for which `predicate` returned False
"""
def split_by_predicate[T](iterable: Iterable[T], predicate: Callable[[T], bool]) -> tuple[list[T], list[T]] {
    (matched, unmatched) = ([], []);
    for item in iterable {
        if predicate(item) {
            matched.append(item);
        } else {
            unmatched.append(item);
        }
    }
    return (matched, unmatched);
}
