"""Merges two arrays in increasing order."""
def merge_helper(arr1: list[int], arr2: list[int]) -> list[int] {
    i = 0;
    j = 0;
    ret: list[int] = [];
    while i < len(arr1) and j < len(arr2) {
        if arr1[i] < arr2[j] {
            ret.append(arr1[i]);
            i += 1;
        } elif arr2[j] < arr1[i] {
            ret.append(arr2[j]);
            j += 1;
        } else {
            ret.append(arr1[i]);
            ret.append(arr2[j]);
            j += 1;
            i += 1;
        }
    }
    while i < len(arr1) {
        ret.append(arr1[i]);
        i += 1;
    }
    while j < len(arr2) {
        ret.append(arr2[j]);
        j += 1;
    }
    return ret;
}
