```jac
""" TaylorT2 2PN Quadrupolar Tidal Coefficient, v^14 Phasing Term.

   XA = mass fraction of object
   chiA = aligned spin-orbit component of object
   chiB = aligned spin-orbit component of companion object
   AqmA = dimensionless spin-induced quadrupole moment of object
   AqmB = dimensionless spin-induced quadrupole moment of companion object
   alpha2PNT = 2PN Quadrupole Tidal Flux coefficient """
def PNT2Tidal_Pv14(
    XA: float,
    chiA: float = 0,
    chiB: float = 0,
    AqmA: float = 0,
    AqmB: float = 0,
    alpha2PNT: float = 0
) -> float {
    XATo2nd = XA * XA;
    XATo3rd = XATo2nd * XA;
    XATo4th = XATo3rd * XA;
    XATo5th = XATo4th * XA;
    return (
        ((351560665 / 254016) + ((5 * alpha2PNT) / 9))
        - ((738971515 * XA) / 1524096)
        - ((104525 * XATo2nd) / 336)
        - ((2160965 * XATo3rd) / 6048)
        - ((7310 * XATo4th) / 27)
        + ((4285 * XATo5th) / 36)
        + (
            (
                (-(1065 * XATo2nd) / 8)
                + ((875 * XATo3rd) / 8)
                + (AqmA * ((-130 * XATo2nd) + ((320 * XATo3rd) / 3)))
            )
            * chiA
            * chiA
        )
        + (
            (((-(1015 * XA) / 4) + ((1385 * XATo2nd) / 3)) - ((2495 * XATo3rd) / 12))
            * chiA
            * chiB
        )
        + (
            (
                (((-1065 / 8) + ((3005 * XA) / 8)) - ((2815 * XATo2nd) / 8))
                + ((875 * XATo3rd) / 8)
                + (
                    AqmB
                    * (
                        ((-130 + ((1100 * XA) / 3)) - ((1030 * XATo2nd) / 3))
                        + ((320 * XATo3rd) / 3)
                    )
                )
            )
            * chiB
            * chiB
        )
    );
}
