```jac
"""Sort a list of integers from least to greatest"""
def merge_sort(aList: list[int]) -> list[int] {
    n = len(aList);
    if n <= 1 {
        return aList;
    }
    first = merge_sort(aList[0:int(n / 2)]);
    second = merge_sort(aList[int(n / 2):n]);
    (i, j) = (0, 0);
    firstLen = len(first);
    secondLen = len(second);
    sortedList = [];
    for k in range(n) {
        if i == firstLen {
            sortedList.append(second[j]);
            j += 1;
        } elif j == secondLen {
            sortedList.append(first[i]);
            i += 1;
        } elif first[i] < second[j] {
            sortedList.append(first[i]);
            i += 1;
        } else {
            sortedList.append(second[j]);
            j += 1;
        }
    }
    return sortedList;
}
