```jac
"""Return True if target is found in indicated portion of a Python list.
       The search only considers the portion from data[low] to data[high] inclusive.
    """
def binary_search(data: list[int], target: int, low: int, high: int) -> bool {
    if low > high {
        return False;
    }
    mid = (low + high) // 2;
    if target == data[mid] {
        return True;
    }
    if target < data[mid] {
        return binary_search(data, target, low, mid - 1);
    }
    return binary_search(data, target, mid + 1, high);
}
```

```jac
"""Compare modify and current payloads; return True if they differ."""
def compare_payloads(
    modify_payload: dict[str, dict | str | int | float | bool | None],
    current_payload: dict[str, dict | str | int | float | bool | None] | None
) -> bool {
    for (key, val) in modify_payload.items() {
        if current_payload is None or current_payload.get(key) is None {
            return True;
        } elif isinstance(val, dict) {
            nested = current_payload.get(key);
            if compare_payloads(val, nested as dict[str, dict | str | int | float | bool | None] | None) {
                return True;
            }
        } elif val != current_payload.get(key) {
            return True;
        }
    }
    return False;
}
