"""Parse a dict of dicts to generate a list of lists describing
the fields, and an array of the corresponding data records."""
def parseData(data: dict[str, dict[str, int | str | list]]) -> tuple[list[list[str | int]], list[list[int | str | list]]] {
    fields = [];
    records = [];
    for k in list(data.keys()) {
        t = data[k]['Type'] as int;
        l = data[k]['Length'] as int;
        if t == 0 {
            nt = 'C';
            p = 0;
        } elif t == 1 {
            nt = 'N';
            p = 0;
        } elif t == 2 {
            nt = 'N';
            p = data[k]['Precision'] as int;
        } else {
            fields.append([k, t, l, 0]);
            records.append([data[k]['Data']]);
            continue;
        }
        fields.append([k, nt, l, p]);
        records.append([data[k]['Data']]);
    }
    return (fields, records);
}
