```jac
"""Calculates the start offset and number of documents for each client."""
def bounds(
    total_docs: int,
    client_index: int,
    num_clients: int,
    includes_action_and_meta_data: bool
) -> tuple[int, int, int] {
    source_lines_per_doc = 2 if includes_action_and_meta_data else 1;
    docs_per_client: float = total_docs / num_clients;
    start_offset_docs = int(round(docs_per_client * client_index));
    end_offset_docs = int(round(docs_per_client * (client_index + 1)));
    offset_lines = start_offset_docs * source_lines_per_doc;
    docs = end_offset_docs - start_offset_docs;
    lines = docs * source_lines_per_doc;
    return (offset_lines, docs, lines);
}
```

```jac
"""Merges two sorted sublists into a single sorted list."""
def merge(left: list[int], right: list[int]) -> list[int] {
    ret = [];
    li = ri = 0;
    while li < len(left) and ri < len(right) {
        if left[li] <= right[ri] {
            ret.append(left[li]);
            li += 1;
        } else {
            ret.append(right[ri]);
            ri += 1;
        }
    }
    if li == len(left) {
        ret.extend(right[ri:]);
    } else {
        ret.extend(left[li:]);
    }
    return ret;
}
```

