"""This is the original way to calculate the julian day from the NREL paper.
    However, it is much faster to convert to unix/epoch time and then convert
    to julian day. Note that the date must be UTC."""
def julian_day_dt(
    year: int,
    month: int,
    day: int,
    hour: int,
    minute: int,
    second: int,
    microsecond: int
) -> float {
    if month <= 2 {
        year = year - 1;
        month = month + 12;
    }
    a = int(year / 100);
    b = 2 - a + int(a * 0.25);
    frac_of_day = (microsecond + second + minute * 60 + hour * 3600) * 1.0 / (3600 * 24);
    d = day + frac_of_day;
    jd = int(365.25 * (year + 4716)) + int(30.6001 * (month + 1)) + d + b - 1524.5;
    return jd;
}
```

