"""Convert a match's letter identifier to numbers."""
def matchIdToNumber(matchId: str) -> int {
    id_sum = 0;
    for letter in matchId {
        value = ord(letter.upper()) - 64;
        if value < 1 or value > 26 {
            raise ValueError(
                "Match identifier should only contain letters (got '{}')".format(letter)
            );
        }
        id_sum += value;
    }
    return id_sum;
}
