```jac
"""
    Return minimum number of precincts that could be "bad".
       L = list of n precincts: n (size,name) pairs
       M = margin of victory as number of votes separating winner
           from runner-up
       s = maximum within-precinct miscount
    """
def bmin(L: list[tuple[int, str]], M: int, s: float = 0.2) -> int {
    assert 0 <= M <= sum(x[0] for x in L);
    votes_so_far = 0.0;
    k = 0;
    while votes_so_far < M and k < len(L) {
        votes_so_far += 2.0 * s * L[k][0];
        k += 1;
    }
    return k;
}
```

```jac
"""Change a text with TEXT[ABC..] into a list with [TEXTA, TEXTB, TEXC, ...
if no bracket is used it just return the a list with the single text
It uses recursivity to allow several [] in the text"""
def expand_brackets(text: str | None) -> list[str] | tuple[None] {
    if text is None {
        return (None,);
    }
    start = text.find("[");
    end = text.find("]");
    if start < 0 or end < 0 {
        return [text];
    }
    text_list: list[str] = [];
    for char in text[start + 1:end] {
        text_list += expand_brackets(text[:start] + char + text[end + 1:]);
    }
    return text_list;
}
```

