    """
def search_codetree_hasleftsub(tword: str, codetree: dict[str, list]) -> int {
    pos = 0;
    while True {
        s = tword[pos];
        if s not in codetree {
            return 0;
        } elif codetree[s][0] > 0 {
            return codetree[s][0];
        } elif pos == len(tword) - 1 {
            return 0;
        } else {
            pos += 1;
            codetree = codetree[s][1];
        }
    }
}
