Will return 0 if the argument has unexpected form."""
def human_to_real(iops: str) -> int {
    prefix = iops[:-1];
    unit = iops[-1];
    if prefix.isdigit() {
        result = int(prefix);
        if unit == 'M' {
            result *= 1000000;
        } elif unit == 'K' {
            result *= 1000;
        } else {
            result = 0;
        }
        return result;
    }
    return 0;
}
