            continue;
        }
        if element == value {
            value = 0;
            shallow_list.append(element);
            break;
        }
        if element < value {
            shallow_list.append(element);
            value -= element;
        }
    }
    if value != 0 {
        return [];
    }
    return shallow_list;
}
