"""Returns a lower-case under-score separated format of the supplied name, which is supposed to be camel-case:
    >>> ToScriptName("AbcABC01ABCAbc")
    "abc_abc01abc_abc"
    """
def to_lower_case(name: str) -> str {
    script_name = "";
    for i in range(len(name)) {
        ch = name[i];
        if (
            i > 0
            and (
                name[i - 1].islower()
                or name[i - 1].isdigit()
                or (i + 1 < len(name) and name[i + 1].islower())
            )
            and ch.isupper()
        ) {
            script_name += "_";
        }
        script_name += ch.lower();
    }
    return script_name;
}
